-- In-process RPC execution runs under a non-bypass role, scoped for this transaction only.
create function public.classroom_rpc(p_classroom uuid,p_actor uuid,p_name text,p_args jsonb default '{}'::jsonb) returns jsonb language plpgsql security invoker set search_path=public as $$
declare f record; arg_sql text:=''; i integer; typ text; expression text; result jsonb;
begin
 if not exists(select 1 from classrooms where id=p_classroom) then raise exception 'ไม่พบห้องเรียน';end if;
 if p_name like 'classroom_%' or p_name in ('request_classroom','authorize_reminder_worker') then raise exception 'RPC not allowed';end if;
 select p.* into f from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname=p_name and p.prokind='f' and has_function_privilege('service_role',p.oid,'EXECUTE') and not exists(select 1 from jsonb_object_keys(p_args) k where not(k=any(p.proargnames))) and not exists(select 1 from generate_series(1,p.pronargs-p.pronargdefaults) k where not(p_args ? p.proargnames[k])) order by p.pronargs limit 1;
 if f.oid is null then raise exception 'Unknown classroom RPC';end if;
 for i in 1..f.pronargs loop
  if p_args ? f.proargnames[i] then
   typ:=format_type(f.proargtypes[i-1],null);
   if typ in ('json','jsonb') then expression:=format('($1->%L)::%s',f.proargnames[i],typ);
   elsif typ like '%[]' then expression:=format('case when $1->%L=''null''::jsonb then null else array(select jsonb_array_elements_text($1->%L))::%s end',f.proargnames[i],f.proargnames[i],typ);
   else expression:=format('($1->>%L)::%s',f.proargnames[i],typ);end if;
   arg_sql:=arg_sql||case when arg_sql='' then '' else ',' end||format('%I => %s',f.proargnames[i],expression);
  end if;
 end loop;
 perform set_config('app.classroom',p_classroom::text,true);perform set_config('app.actor',coalesce(p_actor::text,''),true);
 execute 'set local role finance_classroom';
 if f.proretset then execute format('select coalesce(jsonb_agg(to_jsonb(x)),''[]''::jsonb) from public.%I(%s) x',p_name,arg_sql) into result using p_args;
 else execute format('select to_jsonb(public.%I(%s))',p_name,arg_sql) into result using p_args;end if;
 execute 'set local role service_role';return result;
end;$$;
revoke all on function public.classroom_rpc(uuid,uuid,text,jsonb) from public,anon,authenticated;
grant execute on function public.classroom_rpc(uuid,uuid,text,jsonb) to service_role;
-- Preserve existing business rules under classroom RLS.
do $$ declare f record; src text;begin
 for f in select p.oid,p.proname from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.prokind='f' and p.proname not like 'classroom_%' loop
  execute format('grant execute on function %s to finance_classroom',f.oid::regprocedure);
  if f.proname='manage_payment_qr' then src:=replace(pg_get_functiondef(f.oid),'on conflict(amount_cents)','on conflict(classroom_id,amount_cents)');execute src;end if;
 end loop;
end $$;
create function public.classroom_create(p_actor uuid,p_name text,p_owner uuid default null) returns uuid language plpgsql security invoker set search_path=public as $$
declare owner uuid:=coalesce(p_owner,p_actor); result uuid; super boolean;
begin
 perform pg_advisory_xact_lock(7086399);
 select is_super into super from classroom_admins a join profiles p on p.id=a.profile_id where a.profile_id=p_actor and p.active and p.deleted_at is null;
 if super is null or (owner<>p_actor and not super) then raise exception 'ไม่มีสิทธิ์สร้างห้องเรียน';end if;
 if not exists(select 1 from classroom_admins where profile_id=owner) then raise exception 'เลือกแอดมินห้องเรียน';end if;
 if not super and exists(select 1 from classrooms where owner_id=owner) then raise exception 'สร้างห้องได้ 1 ห้อง หากต้องการเพิ่มให้ติดต่อผู้ดูแลหลัก';end if;
 insert into classrooms(name,owner_id) values(trim(p_name),owner) returning id into result;
 update profiles set classroom_id=result where id=owner and classroom_id is null;
 insert into site_settings(id,data,classroom_id) values(true,'{"siteName":"Finance MEDTECH","bankName":"","accountName":"","accountNumber":"","paymentQrUrl":"","lineOaUrl":"https://lin.ee/7VYJbx0"}',result);
 insert into evidence_storage_settings(id,classroom_id) values(true,result);
 return result;
end;$$;
revoke all on function public.classroom_create(uuid,text,uuid) from public,anon,authenticated;
grant execute on function public.classroom_create(uuid,text,uuid) to service_role;
create or replace function public.evidence_storage_usage() returns jsonb language sql security invoker set search_path=public as $$
 select jsonb_build_object('used_bytes',coalesce((select sum(size) from evidence_files where state in ('active','pending','deleting')),0),'file_count',(select count(*) from evidence_files where state in ('active','pending','deleting')),'budget_bytes',budget_bytes,'auto_cleanup',auto_cleanup,'trigger_percent',90,'target_percent',80) from evidence_storage_settings where id;
$$;
